#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct PerformanceReliabilityContractRequest{pub request_id:String,pub consumer:String,pub producer:String,pub semantic_profile:String,pub negotiated_version:String,pub workload_order:Vec<String>,pub retained_workload_order:Vec<String>,pub missing_workload_order:Vec<String>,pub replay_identity:ContentHash,pub policy_allow:bool,pub protected_closure:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub network_available:bool,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct PerformanceReliabilityContractReceipt{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub consumer:String,pub producer:String,pub semantic_profile:String,pub negotiated_version:String,pub compatibility:String,pub disposition:String,pub workload_order:Vec<String>,pub retained_workload_order:Vec<String>,pub missing_workload_order:Vec<String>,pub degraded_workload_order:Vec<String>,pub reliability_issue_order:Vec<String>,pub replay_identity:ContentHash,pub contract_digest:ContentHash,pub effect_receipts:Vec<String>,pub artifact:serde_json::Value,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum PerformanceReliabilityContractError{#[error("invalid reliability contract request: {0}")]Invalid(String),#[error("invalid reliability contract receipt: {0}")]Receipt(String),#[error("reliability contract artifact failed: {0}")]Artifact(String)}
fn h(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn o(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}
impl PerformanceReliabilityContractReceipt{pub fn validate(&self)->Result<(),PerformanceReliabilityContractError>{if self.schema_version!="aurora-research-contract/1.0"||self.boundary!=BOUNDARY||self.artifact.get("boundary").and_then(|v|v.as_str())!=Some(BOUNDARY)||self.artifact.get("content_type").and_then(|v|v.as_str())!=Some(CONTENT_TYPE)||!self.raw_data_local||!self.aggregate_only||self.workload_order.is_empty()||![&self.replay_identity,&self.contract_digest].into_iter().all(h)||self.artifact.get("content_hash").and_then(|v|v.as_str())!=Some(self.contract_digest.as_str()){return Err(PerformanceReliabilityContractError::Receipt("reliability contract identity or digest is incomplete".into()))}for v in [&self.workload_order,&self.retained_workload_order,&self.missing_workload_order,&self.degraded_workload_order,&self.reliability_issue_order,&self.effect_receipts]{if !o(v){return Err(PerformanceReliabilityContractError::Receipt("reliability contract ordering is not canonical".into()))}}let ids=self.workload_order.iter().cloned().collect::<BTreeSet<_>>();let parts=self.retained_workload_order.iter().chain(&self.missing_workload_order).cloned().collect::<BTreeSet<_>>();if ids!=parts{return Err(PerformanceReliabilityContractError::Receipt("reliability contract workloads do not partition".into()))}Ok(())}}
