pub fn negotiate(r:&PerformanceReliabilityContractRequest,feature_id:&str,version:&str,_scale:&str,_federated:bool)->Result<PerformanceReliabilityContractReceipt,PerformanceReliabilityContractError>{if r.request_id.trim().is_empty()||r.consumer.trim().is_empty()||r.producer.trim().is_empty()||r.workload_order.is_empty()||r.boundary!=BOUNDARY||!r.raw_data_local||!r.aggregate_only||!h(&r.replay_identity){return Err(PerformanceReliabilityContractError::Invalid("reliability contract request is invalid".into()))}let fields=r.workload_order.iter().cloned().collect::<BTreeSet<_>>();let retained=r.retained_workload_order.iter().filter(|x|fields.contains(*x)).cloned().collect::<BTreeSet<_>>();let missing=fields.difference(&retained).cloned().collect::<BTreeSet<_>>();let mut issues:BTreeSet<String>=BTreeSet::new();if !r.policy_allow{issues.insert("policy-denied".into());}if !r.protected_closure{issues.insert("protected-closure-incomplete".into());}if !r.network_available{issues.insert("network-unavailable".into());}let disposition=if !issues.is_empty(){"blocked"}else if retained.is_empty(){"unresolved"}else if missing.is_empty(){"compatible"}else{"partial"};let payload=json!({"schema_version":"aurora-research-contract/1.0","contract_version":version,"feature_id":feature_id,"request_id":r.request_id,"consumer":r.consumer,"producer":r.producer,"semantic_profile":r.semantic_profile,"negotiated_version":r.negotiated_version,"compatibility":if disposition=="compatible"{"compatible"}else{"additive-migration"},"disposition":disposition,"workload_order":fields,"retained_workload_order":retained,"missing_workload_order":missing,"degraded_workload_order":Vec::<String>::new(),"reliability_issue_order":issues,"replay_identity":r.replay_identity,"effect_receipts":["none:reliability-contract-validation"],"raw_data_local":true,"aggregate_only":true,"boundary":BOUNDARY});let d=ContentHash::of_value(&payload).map_err(|e|PerformanceReliabilityContractError::Artifact(e.to_string()))?;let strings=|k:&str|payload[k].as_array().map(|a|a.iter().filter_map(|v|v.as_str().map(String::from)).collect()).unwrap_or_default();let out=PerformanceReliabilityContractReceipt{schema_version:"aurora-research-contract/1.0".into(),contract_version:version.into(),feature_id:feature_id.into(),request_id:r.request_id.clone(),consumer:r.consumer.clone(),producer:r.producer.clone(),semantic_profile:r.semantic_profile.clone(),negotiated_version:r.negotiated_version.clone(),compatibility:if disposition=="compatible"{"compatible"}else{"additive-migration"}.into(),disposition:disposition.into(),workload_order:strings("workload_order"),retained_workload_order:strings("retained_workload_order"),missing_workload_order:strings("missing_workload_order"),degraded_workload_order:vec![],reliability_issue_order:strings("reliability_issue_order"),replay_identity:r.replay_identity.clone(),contract_digest:d.clone(),effect_receipts:vec!["none:reliability-contract-validation".into()],artifact:json!({"content_type":CONTENT_TYPE,"content_hash":d,"boundary":BOUNDARY}),raw_data_local:true,aggregate_only:true,boundary:BOUNDARY.into()};out.validate()?;Ok(out)}

